811					agentType = result.Metadata.Agent
812				}
813			}
814		}
815	
816		// Read transcript (auto-fetches blobs if needed)
817		if transcript, transcriptErr := readTranscriptFromTree(ctx, sessionTree, agentType); transcriptErr == nil && transcript != nil {
818			result.Transcript = transcript
819		}
820	
