854	// This is useful when you have the session ID but don't know its index within the checkpoint.
855	// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
856	// Returns an error if no session with the given ID exists in the checkpoint.
857	func (s *GitStore) ReadSessionContentByID(ctx context.Context, checkpointID id.CheckpointID, sessionID string) (*SessionContent, error) {
858		summary, err := s.ReadCommitted(ctx, checkpointID)
859		if err != nil {
860			return nil, err
861		}
862		if summary == nil {
863			return nil, ErrCheckpointNotFound
864		}
865	
866		// Iterate through sessions to find the one with matching session ID
867		for i := range len(summary.Sessions) {
868			content, readErr := s.ReadSessionContent(ctx, checkpointID, i)
869			if readErr != nil {
870				continue
871			}
872			if content != nil && content.Metadata.SessionID == sessionID {
873				return content, nil
874			}
875		}
876	
877		return nil, fmt.Errorf("session %q not found in checkpoint %s", sessionID, checkpointID)
878	}
